import{Z as t,e as s,f as i,a0 as a}from"./chunks/framework.DmpHOl9T.js";const u=JSON.parse('{"title":"How to Conditionally Redirect Users Based on Their Input","description":"","frontmatter":{},"headers":[],"relativePath":"guides/templating-theming/how-to-conditionally-redirect-users-based-on-their-input.md","filePath":"guides/templating-theming/how-to-conditionally-redirect-users-based-on-their-input.md","lastUpdated":1782532814000}'),n={name:"guides/templating-theming/how-to-conditionally-redirect-users-based-on-their-input.md"};function r(o,e,d,l,h,c){return s(),i("div",null,[...e[0]||(e[0]=[a(`<h1 id="how-to-conditionally-redirect-users-based-on-their-input" tabindex="-1">How to Conditionally Redirect Users Based on Their Input <a class="header-anchor" href="#how-to-conditionally-redirect-users-based-on-their-input" aria-label="Permalink to &quot;How to Conditionally Redirect Users Based on Their Input&quot;">​</a></h1><p>Sometimes the thank-you destination should depend on what the user submitted — send opted-in users to one URL and everyone else to another, route by department, or branch on a quiz score. Formie supports this natively with <strong>Redirect Rules</strong>; the patterns below cover cases where you need more control.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>A form with submit action set to <strong>URL</strong> or <strong>Entry</strong></li><li>Familiarity with <a href="/forms/conditions">Conditions</a> and <a href="/developers/reference-tokens">Reference tokens</a></li></ul><h2 id="use-redirect-rules-recommended" tabindex="-1">Use Redirect Rules (Recommended) <a class="header-anchor" href="#use-redirect-rules-recommended" aria-label="Permalink to &quot;Use Redirect Rules (Recommended)&quot;">​</a></h2><p>Formie adds <strong>Enable Redirect Rules</strong> in form settings. Each rule has conditions and a redirect target. Rules are evaluated in order; the first match wins.</p><ol><li>Open your form in the form builder</li><li>Under submit settings, enable <strong>Enable Redirect Rules</strong></li><li>Add rules with conditions (for example, &quot;Agree field is checked&quot;) and set each rule&#39;s redirect URL or entry</li></ol><p>This works for both page-reload and Ajax forms, stays in the control panel, and does not require custom code. Prefer this approach whenever it covers your logic.</p><h2 id="use-an-account-only-intermediary-template" tabindex="-1">Use an Account-Only Intermediary Template <a class="header-anchor" href="#use-an-account-only-intermediary-template" aria-label="Permalink to &quot;Use an Account-Only Intermediary Template&quot;">​</a></h2><p>If a redirect needs server-side logic that the built-in rules cannot express, first establish access to the submission. Follow <a href="/guides/templating-theming/build-a-success-page-for-your-form#show-answers-to-the-signed-in-submitter">the signed-in summary pattern</a>, including collection of the current user, the form and site filters, and the ownership check.</p><p>After that template has obtained the authorised <code>submission</code>, replace its output with this partial Twig snippet. It assumes your form has a Dropdown field with handle <code>department</code>, whose saved values include <code>sales</code>:</p><div class="language-twig vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">twig</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{% </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> submission.getFieldValueAsString(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;department&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">==</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;sales&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> %}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    {% redirect </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;/sales/thanks&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> %}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{% </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">else</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> %}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    {% redirect </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;/support/thanks&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> %}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{% </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">endif</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> %}</span></span></code></pre></div><p>Create both destination templates before testing. Submit each choice as the owning user and confirm the destination. Then open the intermediary URL from another account and confirm it cannot read or branch on that submission. Do not fetch arbitrary numeric submission IDs or use a submitted email address to decide ownership.</p><p>Use fixed server-controlled destinations. A hidden input is still editable by the visitor and should not decide access to a resource. For public forms without account ownership, use the built-in redirect rules above and keep the destination page free of private submission content.</p><h2 id="test-the-redirect-rules" tabindex="-1">Test the Redirect Rules <a class="header-anchor" href="#test-the-redirect-rules" aria-label="Permalink to &quot;Test the Redirect Rules&quot;">​</a></h2><p>Submit answers matching the first rule and check the URL. Repeat for a later rule and for answers matching none. Check both valid and invalid form input: a failed validation must not take the visitor to a success page. If several rules match, verify that their order produces the intended first match.</p>`,16)])])}const m=t(n,[["render",r]]);export{u as __pageData,m as default};
